  const rd2 = Math.tanh((aS*0.6 - iS*1.1 + hS + spiral2 + ripple)*1.8);
  const rdMix = Math.tanh(rd1*1.3 + rd2*0.7 + Math.sin(rd1*rd2*3)*0.3);
